package com.tickethub.paymentservice.security;
import io.jsonwebtoken.Claims; import io.jsonwebtoken.Jwts; import io.jsonwebtoken.security.Keys; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import javax.crypto.SecretKey; import java.io.IOException; import java.nio.charset.StandardCharsets; import java.util.*;
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter {
 private final SecretKey publicKey,internalKey;
 public JwtAuthenticationFilter(@Value("${security.jwt.secret}") String pub,@Value("${security.internal-jwt-secret}") String internal){publicKey=Keys.hmacShaKeyFor(pub.getBytes(StandardCharsets.UTF_8));internalKey=Keys.hmacShaKeyFor(internal.getBytes(StandardCharsets.UTF_8));}
 @Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{ String h=req.getHeader("Authorization"); if(h!=null&&h.startsWith("Bearer ")){String token=h.substring(7); try{set(parse(token,publicKey));}catch(Exception e){try{set(parse(token,internalKey));}catch(Exception ignored){SecurityContextHolder.clearContext();}}} chain.doFilter(req,res); }
 private Claims parse(String t,SecretKey k){return Jwts.parser().verifyWith(k).build().parseSignedClaims(t).getPayload();}
 private void set(Claims c){List<SimpleGrantedAuthority>a=new ArrayList<>(); Object role=c.get("role"); if(role!=null)a.add(new SimpleGrantedAuthority("ROLE_"+clean(role.toString()))); Object roles=c.get("roles"); if(roles instanceof Collection<?> x)x.forEach(r->a.add(new SimpleGrantedAuthority("ROLE_"+clean(r.toString())))); String sub=c.getSubject(); if(sub==null||sub.isBlank())throw new IllegalArgumentException("JWT subject missing"); String email=c.get("email",String.class); SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(new JwtPrincipal(sub,email),null,a));}
 private String clean(String r){return r.startsWith("ROLE_")?r.substring(5):r;}
 public record JwtPrincipal(String userId,String email){}
}
